mapper.select:
select count(id)
from sys_user
where id_card_hash = #{idCardHash}

select count(id)
from sys_register_application
where id_card_hash = #{idCardHash}

select count(id)
from sys_organization
where unified_social_credit_code = #{creditCode}

select count(id)
from sys_register_application
where unified_social_credit_code = #{creditCode}

select count(id)
from sys_register_application
where phone = #{phone}

select ra.id, ra.type, ra.name, ra.phone, ra.unified_social_credit_code, ra.legal_person_name, ra.business_license_attachment_id, ra.verify_status, ra.verify_remark, ra.verify_user, ra.verify_time, ra.create_time, ra.user_id, tp.id as plan_id, tp.version as plan_version, tp.status as plan_status, tp.expire_time as plan_expire_time, (select max(ll.create_time) from sys_login_log ll where ll.operator = ra.user_id) as last_login_time, (case when ra.user_id is null then null else (select count(distinct from_unixtime(ll.create_time / 1000, '%Y-%m-%d')) from sys_login_log ll where ll.operator = ra.user_id) end) as usage_days, (case when ra.user_id is null then null else (select exists(select 1 from sys_organization_user ou where ou.user_id = ra.user_id and ou.enable = 1)) end) as enabled from sys_register_application ra left join sys_user su on su.id = ra.user_id left join tenant_plan tp on tp.organization_id = su.last_organization_id
and (ra.verify_status != 'APPROVED' or tp.status is null or tp.status = 'FREE')
and ra.type = #{request.type}
and ra.verify_status = #{request.verifyStatus}
and (ra.name like concat('%', #{request.keyword}, '%') or ra.phone like concat('%', #{request.keyword}, '%'))
order by ra.create_time desc
